mapper.select:
SELECT  FROM im_moderation_action
 WHERE guild_kind = #{guildKind} AND guild_id = #{guildId}
   AND target_member_id = #{targetMemberId}
   AND id < #{beforeId}
 ORDER BY id DESC LIMIT #{limit}

SELECT  FROM im_moderation_appeal
 WHERE guild_kind = #{guildKind} AND guild_id = #{guildId}
   AND appellant_member_id = #{memberId}
 ORDER BY id DESC LIMIT 50

SELECT id, guild_kind AS guildKind, guild_id AS guildId, name, position, permissions, mentionable, status,
       is_system AS isSystem, version, color, hoist, display_level AS displayLevel
  FROM im_guild_role WHERE id = #{id}

mapper.update:
UPDATE im_guild_role SET name = #{name}, position = #{position}, permissions = #{permissions}, mentionable = #{mentionable},
       status = #{status}, color = #{color}, hoist = #{hoist}, version = version + 1
 WHERE id = #{id} AND version = #{expectedVersion}

mapper.select:
SELECT m.role_id FROM im_guild_role_member m JOIN im_guild_role r ON r.id = m.role_id
 WHERE r.guild_kind = #{guildKind} AND r.guild_id = #{guildId} AND m.member_id = #{memberId}
 ORDER BY m.role_id
